import os
import asyncio
import logging
import uuid
import re
import json
from typing import Optional, List, Dict, Any, Union, Tuple
from pathlib import Path
from dataclasses import dataclass, field
from PIL import Image

from backend.config import get_server_credentials, save_server_credentials

logger = logging.getLogger("gemini_wrapper")

@dataclass
class GeminiImage:
    """Wrapper for images generated by Google Gemini (Imagen 3)."""
    url: str
    title: str = ""
    alt: str = ""
    raw_image: Any = None

    async def save(self, path: Union[str, Path], filename: Optional[str] = None) -> str:
        """Saves the generated image to local disk."""
        dest_dir = Path(path)
        dest_dir.mkdir(parents=True, exist_ok=True)
        if self.raw_image and hasattr(self.raw_image, "save"):
            saved_path = await self.raw_image.save(path=str(dest_dir), filename=filename)
            return str(saved_path)
        raise RuntimeError("No underlying image object available to save.")


@dataclass
class GeminiResponse:
    """Structured response from Gemini Web containing text, thoughts, images, and metadata."""
    text: str
    thoughts: Optional[str] = None
    images: List[GeminiImage] = field(default_factory=list)
    model_used: Optional[str] = None
    citations: List[Any] = field(default_factory=list)
    candidates: List[Any] = field(default_factory=list)
    raw_output: Any = None

    @property
    def has_images(self) -> bool:
        return len(self.images) > 0


class GeminiChatSession:
    """Multi-turn conversational chat session preserving context across multiple messages."""

    def __init__(self, wrapper: "GeminiWebWrapper", session_id: Optional[str] = None, model: Optional[str] = None):
        self.wrapper = wrapper
        self.session_id = session_id or str(uuid.uuid4())
        self.model = model
        self.raw_session: Any = None
        self.history: List[Dict[str, Any]] = []

    async def _ensure_session(self, force_new: bool = False):
        if not self.raw_session or force_new:
            client = await self.wrapper.get_client()
            chosen_model = None
            if self.model:
                chosen_model = self.wrapper.resolve_model(client, self.model)
            if chosen_model:
                self.raw_session = client.start_chat(model=chosen_model)
            else:
                self.raw_session = client.start_chat()

    async def send_message(
        self,
        prompt: str,
        files: Optional[List[Union[str, Path]]] = None,
        extended_thinking: bool = False
    ) -> GeminiResponse:
        """Sends a message in the conversational turn and appends to history. Automatically refreshes cookies if auth fails."""
        max_attempts = 2
        last_error = None

        for attempt in range(max_attempts):
            try:
                await self._ensure_session()

                raw_files = [str(f) for f in files] if files else None
                output = await self.raw_session.send_message(
                    prompt,
                    files=raw_files,
                    extended_thinking=extended_thinking
                )

                response = self.wrapper._wrap_output(output)

                # Check if response text indicates unauthenticated refusal
                if "Are you signed in?" in response.text and attempt < max_attempts - 1:
                    logger.warning("Gemini replied with sign-in prompt in chat. Refreshing cookies and retrying...")
                    refreshed = await self.wrapper.refresh_session(force=True)
                    if refreshed:
                        await self._ensure_session(force_new=True)
                        continue

                self.history.append({
                    "role": "user",
                    "content": prompt,
                    "files": raw_files
                })
                self.history.append({
                    "role": "model",
                    "content": response.text,
                    "thoughts": response.thoughts,
                    "images": [img.url for img in response.images]
                })

                return response

            except Exception as e:
                last_error = e
                if self.wrapper.is_auth_error(e) and attempt < max_attempts - 1:
                    logger.warning(f"Auth error in chat turn: {e}. Refreshing cookies and retrying...")
                    refreshed = await self.wrapper.refresh_session(force=True)
                    if refreshed:
                        await self._ensure_session(force_new=True)
                        continue
                raise last_error


class GeminiWebWrapper:
    """
    Reverse-engineered Python wrapper for Google Gemini Web app.
    Features:
    - Persistent session with background auto-cookie rotation (__Secure-1PSIDTS).
    - Automatic cookie refresh on failed authorization (401, UNAUTHENTICATED, session expiry).
    - Multi-source credential resolution (Settings, Env, g-WRAP cookies.json, Method B browser discovery).
    - Event loop affinity protection to avoid 'Future attached to different loop' in async servers.
    - Full multimodal capabilities: Text, Chain-of-thought Thinking, and Native Imagen 3 Image Generation.
    - Model selection (Pro Advanced, Flash, Thinking, Standard Pro).
    - Multi-turn Chat Sessions.
    """
    _instance: Optional["GeminiWebWrapper"] = None

    def __init__(self):
        self.client = None
        self.psid: Optional[str] = None
        self.psidts: Optional[str] = None
        self._watcher_task: Optional[asyncio.Task] = None
        self._initialized = False
        self._loop: Optional[asyncio.AbstractEventLoop] = None
        self._lock: Optional[asyncio.Lock] = None
        self._chat_sessions: Dict[str, GeminiChatSession] = {}

    @classmethod
    def get_instance(cls) -> "GeminiWebWrapper":
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    @staticmethod
    def extract_cookie_pair(cookie_input: Optional[str]) -> Tuple[Optional[str], Optional[str]]:
        """Extracts (__Secure-1PSID, __Secure-1PSIDTS) from cookie string, header, or combined token."""
        if not cookie_input:
            return None, None
        raw = str(cookie_input).strip()

        psid = None
        psidts = None

        if "__Secure-1PSID" in raw:
            m_psid = re.search(r"__Secure-1PSID=([A-Za-z0-9_\-\.]+)", raw)
            if m_psid:
                psid = m_psid.group(1).strip()
            m_ts = re.search(r"__Secure-1PSIDTS=([A-Za-z0-9_\-\.]+)", raw)
            if m_ts:
                psidts = m_ts.group(1).strip()

        if not psid:
            if "|" in raw:
                parts = raw.split("|", 1)
                psid = parts[0].strip()
                psidts = parts[1].strip()
            elif not raw.startswith("{"):
                psid = raw

        return psid, psidts

    def _get_active_credentials(self) -> Tuple[Optional[str], Optional[str]]:
        """Resolves credentials from settings, env, or local g-WRAP cookies.json."""
        creds = get_server_credentials()
        psid = creds.get("gemini_cookie_psid") or os.environ.get("GEMINI_COOKIE_PSID")
        psidts = creds.get("gemini_cookie_psidts") or os.environ.get("GEMINI_COOKIE_PSIDTS")

        if not psid:
            raw = os.environ.get("GEMINI_COOKIE", "")
            extracted_psid, extracted_ts = self.extract_cookie_pair(raw)
            if extracted_psid:
                psid = extracted_psid
                if extracted_ts:
                    psidts = extracted_ts

        # Fallback: check g-WRAP cookies.json
        if not psid:
            for potential_path in [
                Path("d:/VS/g-WRAP/cookies.json"),
                Path("../g-WRAP/cookies.json"),
                Path("cookies.json")
            ]:
                if potential_path.exists():
                    try:
                        c_data = json.loads(potential_path.read_text(encoding="utf-8"))
                        inner = c_data.get("cookies", c_data)
                        if inner.get("__Secure-1PSID"):
                            psid = inner["__Secure-1PSID"]
                            psidts = inner.get("__Secure-1PSIDTS")
                            logger.info(f"Loaded credentials from {potential_path}")
                            break
                    except Exception:
                        pass

        return psid, psidts

    def _ensure_lock(self, current_loop: asyncio.AbstractEventLoop) -> asyncio.Lock:
        if self._lock is None or self._loop != current_loop:
            self._lock = asyncio.Lock()
        return self._lock

    @staticmethod
    def is_auth_error(exc: Exception) -> bool:
        """Determines if an exception is related to authentication or cookie expiration."""
        msg = str(exc).lower()
        if any(term in msg for term in [
            "unauthenticated",
            "permission denied",
            "401",
            "autherror",
            "session is not authenticated",
            "cookies have expired",
            "are you signed in",
            "reject_code: 7"
        ]):
            return True
        return False

    async def get_client(self, psid_override: Optional[str] = None, psidts_override: Optional[str] = None, force_refresh: bool = False):
        """Initializes or returns persistent GeminiClient with background auto-cookie rotation."""
        current_loop = asyncio.get_running_loop()
        lock = self._ensure_lock(current_loop)

        async with lock:
            active_psid = psid_override or self.psid
            active_psidts = psidts_override or self.psidts

            if not active_psid:
                active_psid, active_psidts = self._get_active_credentials()

            if (
                not force_refresh
                and self.client
                and self._initialized
                and self._loop == current_loop
                and (not active_psid or self.psid == active_psid)
            ):
                if getattr(self.client, "account_status", None) and self.client.account_status.name != "UNAUTHENTICATED":
                    return self.client

            # Clean up prior client if loop or credentials changed
            if self.client:
                try:
                    if self._watcher_task:
                        self._watcher_task.cancel()
                        self._watcher_task = None
                    if self._loop == current_loop:
                        await self.client.close()
                except Exception:
                    pass
                self.client = None
                self._initialized = False

            self._loop = current_loop
            self.psid = active_psid
            self.psidts = active_psidts

            from gemini_webapi import GeminiClient

            # If explicit credentials are available, initialize with them; otherwise fallback to Method B (zero args)
            if self.psid:
                self.client = GeminiClient(
                    secure_1psid=self.psid,
                    secure_1psidts=self.psidts,
                    auto_refresh=True,
                    refresh_interval=300
                )
            else:
                logger.info("No explicit PSID provided; attempting Method B auto-discovery (cache/browser)...")
                self.client = GeminiClient(
                    auto_refresh=True,
                    refresh_interval=300
                )

            await self.client.init(
                timeout=60,
                auto_close=False,
                auto_refresh=True,
                refresh_interval=300
            )

            if getattr(self.client, "account_status", None) and self.client.account_status.name == "UNAUTHENTICATED":
                self._initialized = False
                raise RuntimeError(
                    "Google Gemini Session is UNAUTHENTICATED or cookies have expired. "
                    "Please update cookies in Settings or cookies.json."
                )

            self._initialized = True
            self._watcher_task = asyncio.create_task(self._cookie_sync_loop())

            return self.client

    async def refresh_session(self, force: bool = False) -> bool:
        """
        Actively rotates and refreshes session cookies when authorization fails.
        Syncs newly refreshed cookies to storage and re-initializes client.
        """
        logger.info("Triggered automatic cookie refresh for Gemini session...")
        try:
            # 1. Try rotating cookies via Google RotateCookies endpoint
            if self.client and hasattr(self.client, "_live_client") and self.psid:
                try:
                    from gemini_webapi.utils.rotate_1psidts import rotate_1psidts
                    new_ts = await rotate_1psidts(
                        self.client._live_client,
                        base_psid=self.psid,
                        verbose=True
                    )
                    if new_ts:
                        self.psidts = new_ts
                        save_server_credentials({"gemini_cookie_psidts": new_ts})
                        self._sync_cookies_json(self.psid, new_ts)
                        logger.success("Successfully rotated and refreshed __Secure-1PSIDTS!")
                        await self.get_client(force_refresh=True)
                        return True
                except Exception as rot_err:
                    logger.warning(f"Direct cookie rotation encountered: {rot_err}")

            # 2. Check if g-WRAP cookies.json has fresher credentials
            fresh_psid, fresh_ts = self._get_active_credentials()
            if fresh_psid and (fresh_psid != self.psid or fresh_ts != self.psidts):
                logger.info("Found updated credentials from storage/cookies.json, reapplying...")
                self.psid = fresh_psid
                self.psidts = fresh_ts
                save_server_credentials({"gemini_cookie_psid": fresh_psid, "gemini_cookie_psidts": fresh_ts})
                await self.get_client(force_refresh=True)
                return True

            # 3. Fallback: Re-init client with Method B cache reload
            await self.get_client(force_refresh=True)
            return True

        except Exception as e:
            logger.error(f"Failed to auto-refresh session cookies: {e}")
            return False

    def _sync_cookies_json(self, psid: str, psidts: str):
        """Helper to sync updated tokens back to g-WRAP cookies.json if present."""
        for c_path in [Path("d:/VS/g-WRAP/cookies.json"), Path("cookies.json")]:
            if c_path.exists():
                try:
                    c_data = json.loads(c_path.read_text(encoding="utf-8"))
                    if "cookies" in c_data and isinstance(c_data["cookies"], dict):
                        c_data["cookies"]["__Secure-1PSID"] = psid
                        c_data["cookies"]["__Secure-1PSIDTS"] = psidts
                    else:
                        c_data["__Secure-1PSID"] = psid
                        c_data["__Secure-1PSIDTS"] = psidts
                    c_path.write_text(json.dumps(c_data, indent=2), encoding="utf-8")
                    logger.debug(f"Synced refreshed cookies to {c_path}")
                except Exception:
                    pass

    async def _cookie_sync_loop(self):
        """Monitors client cookies for new rotated __Secure-1PSIDTS and saves to disk."""
        while self.client and self._initialized:
            try:
                await asyncio.sleep(60)
                if not self.client or not self._initialized:
                    break
                
                current_ts = None
                if hasattr(self.client, "cookies") and self.client.cookies:
                    current_ts = self.client.cookies.get("__Secure-1PSIDTS")
                
                if current_ts and current_ts != self.psidts:
                    self.psidts = current_ts
                    save_server_credentials({"gemini_cookie_psidts": current_ts})
                    if self.psid:
                        self._sync_cookies_json(self.psid, current_ts)
                    logger.info("Successfully synced newly rotated __Secure-1PSIDTS to disk!")
            except asyncio.CancelledError:
                break
            except Exception as e:
                logger.debug(f"Cookie sync notice: {e}")

    def resolve_model(self, client: Any, model_name_or_id: Optional[str]) -> Optional[Any]:
        """Resolves model by ID, name, or alias (e.g. gemini-pro, gemini-2.0-flash, gemini-2.5-pro)."""
        if not model_name_or_id or not str(model_name_or_id).strip():
            return None
        req = str(model_name_or_id).strip()

        try:
            return client.resolve_model(req)
        except Exception:
            pass

        req_lower = req.lower().replace("_", "-").replace(" ", "-")
        models = client.list_models() or []
        for m in models:
            m_id = getattr(m, "model_id", "").lower()
            m_name = getattr(m, "model_name", "").lower()
            m_display = getattr(m, "display_name", "").lower()
            aliases = [a.lower() for a in getattr(m, "aliases", []) or []]

            if req_lower == m_id or req_lower in m_name or req_lower in m_display or req_lower in aliases:
                return m

        return None

    def _wrap_output(self, output: Any, model_name: Optional[str] = None) -> GeminiResponse:
        """Wraps gemini_webapi.ModelOutput into a clean GeminiResponse."""
        images: List[GeminiImage] = []

        # 1. Top-level images on ModelOutput
        if hasattr(output, "images") and output.images:
            for img in output.images:
                url = getattr(img, "url", "") or ""
                title = getattr(img, "title", "") or ""
                alt = getattr(img, "alt", "") or ""
                images.append(GeminiImage(url=url, title=title, alt=alt, raw_image=img))

        # 2. Candidate level images
        if not images and hasattr(output, "candidates") and output.candidates:
            for cand in output.candidates:
                cand_imgs = getattr(cand, "generated_images", None) or getattr(cand, "images", None)
                if cand_imgs:
                    for img in cand_imgs:
                        url = getattr(img, "url", "") or ""
                        title = getattr(img, "title", "") or ""
                        alt = getattr(img, "alt", "") or ""
                        images.append(GeminiImage(url=url, title=title, alt=alt, raw_image=img))

        return GeminiResponse(
            text=getattr(output, "text", "") or "",
            thoughts=getattr(output, "thoughts", None),
            images=images,
            model_used=model_name,
            citations=getattr(output, "citations", []) or [],
            candidates=getattr(output, "candidates", []) or [],
            raw_output=output
        )

    async def generate_content(
        self,
        prompt: str,
        files: Optional[List[Union[str, Path]]] = None,
        model: Optional[str] = None,
        extended_thinking: bool = False,
        cookie_override: Optional[str] = None
    ) -> GeminiResponse:
        """
        Executes a single-turn query against Google Gemini Web API.
        Automatically retries with refreshed cookies if an authorization error occurs.
        """
        max_attempts = 2
        last_error = None

        for attempt in range(max_attempts):
            try:
                psid, psidts = self.extract_cookie_pair(cookie_override) if cookie_override else (None, None)
                client = await self.get_client(psid_override=psid, psidts_override=psidts)

                chosen_model = self.resolve_model(client, model) if model else None
                raw_files = [str(f) for f in files] if files else None

                if chosen_model:
                    output = await client.generate_content(
                        prompt,
                        files=raw_files,
                        model=chosen_model,
                        extended_thinking=extended_thinking
                    )
                else:
                    output = await client.generate_content(
                        prompt,
                        files=raw_files,
                        extended_thinking=extended_thinking
                    )

                response = self._wrap_output(output, model_name=getattr(chosen_model, "display_name", None) or model)

                # Check if model gave an unauthenticated text refusal
                if "Are you signed in?" in response.text and attempt < max_attempts - 1:
                    logger.warning("Gemini replied with sign-in prompt. Attempting automatic cookie refresh...")
                    refreshed = await self.refresh_session(force=True)
                    if refreshed:
                        continue

                return response

            except Exception as e:
                last_error = e
                if self.is_auth_error(e) and attempt < max_attempts - 1:
                    logger.warning(f"Auth error during generate_content: {e}. Refreshing cookies and retrying...")
                    refreshed = await self.refresh_session(force=True)
                    if refreshed:
                        continue
                raise last_error

    async def start_chat(self, model: Optional[str] = None, session_id: Optional[str] = None) -> GeminiChatSession:
        """Starts or retrieves a continuous multi-turn chat session."""
        sid = session_id or str(uuid.uuid4())
        if sid in self._chat_sessions:
            return self._chat_sessions[sid]

        session = GeminiChatSession(self, session_id=sid, model=model)
        await session._ensure_session()
        self._chat_sessions[sid] = session
        return session

    async def generate_images(
        self,
        prompt: str,
        output_dir: Union[str, Path] = "temp_gemini",
        width: int = 1280,
        height: int = 720,
        cookie_override: Optional[str] = None
    ) -> List[str]:
        """
        Generates high-fidelity images using Google Imagen 3 via Gemini Web app.
        Automatically retries with refreshed cookies if auth/session fails.
        """
        dest_dir = Path(output_dir)
        dest_dir.mkdir(parents=True, exist_ok=True)

        image_prompt = f"Generate a high quality cinematic illustration of: {prompt}"
        max_attempts = 2
        last_error = None

        for attempt in range(max_attempts):
            try:
                response = await self.generate_content(image_prompt, cookie_override=cookie_override)

                if not response.has_images:
                    if ("Are you signed in?" in response.text or "unauthenticated" in response.text.lower()) and attempt < max_attempts - 1:
                        logger.warning("Image generation denied due to unauthenticated status. Refreshing cookies and retrying...")
                        refreshed = await self.refresh_session(force=True)
                        if refreshed:
                            continue

                    raise RuntimeError(
                        f"Gemini did not return any generated images for prompt. "
                        f"Response text: {response.text[:200] if response.text else 'No text'}"
                    )

                saved_paths: List[str] = []
                for idx, img_obj in enumerate(response.images):
                    temp_filename = f"gemini_gen_{uuid.uuid4().hex[:8]}_{idx}.jpg"
                    saved_raw = await img_obj.save(path=str(dest_dir), filename=temp_filename)

                    if saved_raw and os.path.exists(saved_raw):
                        try:
                            with Image.open(saved_raw) as pil_img:
                                from backend.services.image_service import ImageService
                                fitted = ImageService.fit_image_to_aspect_ratio(None, pil_img, width, height)
                                final_path = dest_dir / f"scene_gemini_{uuid.uuid4().hex[:8]}.jpg"
                                fitted.save(str(final_path), "JPEG", quality=93)
                                try:
                                    os.remove(saved_raw)
                                except Exception:
                                    pass
                                saved_paths.append(str(final_path))
                        except Exception as e:
                            logger.warning(f"Error processing aspect ratio on generated image: {e}")
                            saved_paths.append(str(saved_raw))

                return saved_paths

            except Exception as e:
                last_error = e
                if self.is_auth_error(e) and attempt < max_attempts - 1:
                    logger.warning(f"Auth error during generate_images: {e}. Refreshing cookies and retrying...")
                    refreshed = await self.refresh_session(force=True)
                    if refreshed:
                        continue
                raise last_error

    async def list_available_models(self) -> List[Dict[str, Any]]:
        """Queries and returns live models supported by the authenticated Gemini session."""
        client = await self.get_client()
        raw_models = client.list_models() or []
        result = []
        for m in raw_models:
            result.append({
                "model_id": getattr(m, "model_id", ""),
                "model_name": getattr(m, "model_name", ""),
                "display_name": getattr(m, "display_name", ""),
                "description": getattr(m, "description", ""),
                "capacity": getattr(m, "capacity", ""),
                "is_available": getattr(m, "is_available", True),
                "aliases": getattr(m, "aliases", []) or []
            })
        return result

    async def get_status(self) -> Dict[str, Any]:
        """Returns health and authentication status of the Gemini Web wrapper."""
        has_psid = bool(self.psid or self._get_active_credentials()[0])
        status = "offline"
        account_status = "UNKNOWN"

        if self.client and self._initialized:
            account_status = getattr(self.client.account_status, "name", "AUTHENTICATED")
            status = "online" if account_status != "UNAUTHENTICATED" else "expired"
        elif has_psid:
            status = "ready_to_connect"

        return {
            "status": status,
            "account_status": account_status,
            "has_credentials": has_psid,
            "auto_refresh_active": bool(self._watcher_task and not self._watcher_task.done())
        }

    async def invalidate(self):
        """Invalidates the session and terminates background tasks."""
        try:
            current_loop = asyncio.get_running_loop()
            lock = self._ensure_lock(current_loop)
            async with lock:
                self._initialized = False
                if self._watcher_task:
                    self._watcher_task.cancel()
                    self._watcher_task = None
                if self.client:
                    try:
                        await self.client.close()
                    except Exception:
                        pass
                    self.client = None
                self._chat_sessions.clear()
        except Exception:
            self._initialized = False
            self.client = None
            self._chat_sessions.clear()


# Backward-compatible alias
GeminiWebSessionManager = GeminiWebWrapper
